-- Problem registry, first pass (2026-09-20).
-- Method: clusters found by tag and keyword queries over the 192 analysed items, then each claim checked against upstream
-- sezanzeb/input-remapper at commit cb8f5fd (2026-09-14) by reading the docs and code. Everything here is conf:inferred until a maintainer confirms.
-- Only verified problems are registered; items that could not be checked (GUI behaviour, Restore Defaults flow) are deliberately left out.
UPDATE tag SET value = 'resolved' WHERE facet = 'pr_potential' AND item_n IN (11, 66, 81, 269) AND value IN ('code-fix', 'docs-fix');
